<?php
namespace App\Services;use App\Models\{Committee,CommitteeFunction};
class CommitteeFunctionService{public function __construct(private CommitteeRegulationService $rules,private CommitteeOperationService $operations){}public function synchronize(Committee $committee):void{foreach($this->rules->normativeFunctions($committee->type) as $i=>$function)CommitteeFunction::updateOrCreate(['committee_type'=>$committee->type->value,'committee_id'=>null,'code'=>$function['code']],array_merge($function,['source_type'=>'normative','is_mandatory'=>true,'is_active'=>true,'sort_order'=>$i+1]));}public function createInternal(Committee $committee,array $data,int $userId):CommitteeFunction{$this->operations->ensureActive($committee);$function=$committee->functions()->create(array_merge($data,['committee_type'=>$committee->type->value,'source_type'=>'internal','is_mandatory'=>false,'is_active'=>true]));$this->operations->audit($committee,'internal_function_created',$function,$userId);return$function;}}
